sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.name_ar, d.source_type, d.period FROM entries e JOIN dictionaries d ON e.dictionary_id=d.id WHERE e.headword_norm IN ('منتج','المنتج','مصنع','المصنع','نتاج','النتاج','صناع','الصناع','متصنع','المتصنع') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST LIMIT 120;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
